INSERT INTO `spell_ranks` (`first_spell_id`, `spell_id`, `rank`) SELECT `r`.`first_spell_id`, `m`.`new_id`, `r`.`rank` + `m`.`step` FROM `dc_tmp_rank_map` AS `m` JOIN `spell_ranks` AS `r` ON `r`.`spell_id` = `m`.`top_id`;
INSERT INTO `trainer_spell` (`TrainerId`, `SpellId`, `MoneyCost`, `ReqSkillLine`, `ReqSkillRank`, `ReqAbility1`, `ReqAbility2`, `ReqAbility3`, `ReqLevel`, `VerifiedBuild`) SELECT `t`.`TrainerId`, `m`.`new_id`, `t`.`MoneyCost`, `t`.`ReqSkillLine`, `t`.`ReqSkillRank`, `m`.`prev_id`, `t`.`ReqAbility2`, `t`.`ReqAbility3`, `m`.`band`, 0 FROM `dc_tmp_rank_map` AS `m` JOIN `trainer_spell` AS `t` ON `t`.`SpellId` = `m`.`top_id` WHERE `m`.`is_parent` = 1;
INSERT INTO `spell_bonus_data` (`entry`, `direct_bonus`, `dot_bonus`, `ap_bonus`, `ap_dot_bonus`, `comments`) SELECT `m`.`new_id`, `b`.`direct_bonus`, `b`.`dot_bonus`, `b`.`ap_bonus`, `b`.`ap_dot_bonus`, `b`.`comments` FROM `dc_tmp_rank_map` AS `m` JOIN `spell_bonus_data` AS `b` ON `b`.`entry` = `m`.`bonus_src`;
INSERT INTO `spell_linked_spell` (`spell_trigger`, `spell_effect`, `type`, `comment`) SELECT -`m`.`new_id`, `l`.`spell_effect`, `l`.`type`, `l`.`comment` FROM `dc_tmp_rank_map` AS `m` JOIN `spell_linked_spell` AS `l` ON `l`.`spell_trigger` = -`m`.`top_id`;
