-- DarkChaos: mage spell ranks for levels 81-255 (generated by tools/balance/gen_class_ranks.py)
--
-- 22 spell families get one new rank per band, learned at 81, 100, 130, 160. Spell ids 921000-921259; their Spell.dbc
-- and SkillLineAbility.dbc rows ship with this file (the server needs both DBC files before it).
-- Damage grows like weapon damage and heals/absorbs like player health (tools/balance/gen_reference.py);
-- coefficients, costs and spell class masks are the level-80 rank's. The level-80 ranks are not changed.
--
-- This file adds, for every new rank: the rank chain (spell_ranks), the trainer offer (every trainer that
-- teaches the level-80 rank, at the band level, the previous rank required, same price), the spell power
-- coefficient (spell_bonus_data, copied from the rank the core uses for the level-80 rank) and copies of
-- the level-80 rank's own spell_linked_spell rows.
-- Re-running gives the same result. Apply to acore_world, then restart the worldserver.

DROP TEMPORARY TABLE IF EXISTS `dc_tmp_rank_map`;
CREATE TEMPORARY TABLE `dc_tmp_rank_map` (`new_id` INT NOT NULL PRIMARY KEY, `top_id` INT NOT NULL, `step` TINYINT UNSIGNED NOT NULL, `band` TINYINT UNSIGNED NOT NULL, `prev_id` INT NOT NULL, `is_parent` TINYINT UNSIGNED NOT NULL, `bonus_src` INT NOT NULL DEFAULT 0) ENGINE=InnoDB;
DELETE FROM `dc_tmp_rank_map`;

-- Rank chain
DELETE FROM `spell_ranks` WHERE `spell_id` BETWEEN 921000 AND 921259;

-- Trainer offers
DELETE FROM `trainer_spell` WHERE `SpellId` BETWEEN 921000 AND 921259;

-- Spell power coefficients: the core looks a spell up by its own id, then by its first rank's.
UPDATE `dc_tmp_rank_map` SET `bonus_src` = `top_id` WHERE `top_id` IN (SELECT `entry` FROM `spell_bonus_data`);
UPDATE `dc_tmp_rank_map` AS `m` JOIN `spell_ranks` AS `r` ON `r`.`spell_id` = `m`.`top_id` SET `m`.`bonus_src` = `r`.`first_spell_id` WHERE `m`.`bonus_src` = 0 AND `r`.`first_spell_id` IN (SELECT `entry` FROM `spell_bonus_data`);
DELETE FROM `spell_bonus_data` WHERE `entry` BETWEEN 921000 AND 921259;

-- Links the level-80 rank has under its own id (for example Arcane Missiles ending Arcane Blast)
DELETE FROM `spell_linked_spell` WHERE `spell_trigger` BETWEEN -921259 AND -921000;

DROP TEMPORARY TABLE `dc_tmp_rank_map`;
